import json, re, collections
rows=[json.loads(l) for l in open('commits.jsonl',encoding='utf-8') if l.strip()]
pat=re.compile(r'^([a-z]+)(?:\(([^()\s]+)\))?(!)?: (.+)$')
# summaries ending with period, leading spaces, trailing spaces
odd=[(r['hash'][:7],r['message'].split('\n')[0]) for r in rows if pat.match(r['message'].split('\n')[0]) and (pat.match(r['message'].split('\n')[0]).group(4).endswith(('.', ' ')) or pat.match(r['message'].split('\n')[0]).group(4).startswith(' '))]
print("odd summaries:",len(odd))
for o in odd[:20]: print("  ",o)
# includes candidates (feat/fix/perf/breaking) after exclusions
revs={m.group(1) for r in rows for m in re.finditer(r'This reverts commit ([0-9a-f]+)\.', r['message'])}
print("reverted:",revs)
for r in rows:
    if r['hash'] in revs: print("  reverted commit:",r['hash'][:7],repr(r['message']))
# BREAKING CHANGE footer commit
for r in rows:
    if 'BREAKING CHANGE' in r['message']:
        print("BC footer:",r['hash'][:7],repr(r['message']))
# duplicate Fixes numbers within a commit
for r in rows:
    nums=re.findall(r'^Fixes #(\d+)$', r['message'], re.M)
    if len(nums)!=len(set(nums)): print("dup issues",r['hash'][:7],nums)
# check timestamps duplicates
ts=collections.Counter(r['date'] for r in rows)
print("dup dates:",[d for d,c in ts.items() if c>1][:10])
EOF","description":"Check summary oddities, reverts, duplicates"}

