{"file_path":"/tmp/gen_notes.py","content":"import json
import re
from datetime import datetime

HEADER = re.compile(r"^([a-z]+)(?:\(([^()\s]+)\))?(!)?: (.+)$")
FIXES = re.compile(r"^Fixes #(\d+)$")

rows = [json.loads(l) for l in open("commits.jsonl", encoding="utf-8") if l.strip()]

# mailmap: canonical name by commit email
name_by_email = {}
for line in open(".mailmap", encoding="utf-8"):
    line = line.rstrip("\n")
    if not line.strip() or line.lstrip().startswith("#"):
        continue
    m = re.match(r"^(.*?)\s*<([^>]*)>\s*<([^>]*)>$", line)
    if m:
        name = m.group(1).strip()
        name_by_email[m.group(2)] = name
        name_by_email[m.group(3)] = name


def canon(name, email):
    return name_by_email.get(email, name)


def canon_name(raw, email):
    return name_by_email.get(email, raw)


# reverted hashes
reverted = set()
for r in rows:
    for m in re.finditer(r"This reverts commit ([0-9a-f]{7,40})\.", r["message"]):
        reverted.add(m.group(1))


def is_reverted(h):
    return any(h.startswith(rev) or rev.startswith(h) for rev in reverted)


def coauthors(message):
    out = []
    for line in message.split("\n")[1:]:
        if line.startswith("Co-authored-by:"):
            rest = line[len("Co-authored-by:"):].strip()
            if "<" in rest:
                nm, em = rest.split("<", 1)
                out.append((nm.strip(), em.rstrip(">").strip()))
            else:
                out.append((rest, ""))
    return out


def normalise(summary):
    if not summary:
        return summary
    s = summary[0].upper() + summary[1:]
    if s.endswith("."):
        s = s[:-1]
    return s


included = []
for r in rows:
    msg = r["message"]
    head = msg.split("\n")[0]
    if head.startswith('Revert "'):
        continue
    if is_reverted(r["hash"]):
        continue
    m = HEADER.match(head)
    if not m:
        continue
    typ, scope, bang, summary = m.group(1), m.group(2), m.group(3), m.group(4)
    if scope == "internal" and not bang:
        continue
    if bang:
        section = "breaking"
    elif typ == "feat":
        section = "features"
    elif typ == "fix":
        section = "fixes"
    elif typ == "perf":
        section = "features"
    else:
        continue
    text = normalise(summary)
    if typ == "perf" and section == "features":
        text += " [perf]"
    issues = []
    if typ == "fix":
        for line in msg.split("\n")[1:]:
            fm = FIXES.match(line)
            if fm:
                issues.append(int(fm.group(1)))
    disp = "dependencies" if scope == "deps" else (scope or "general")
    included.append({
        "hash": r["hash"],
        "dt": datetime.fromisoformat(r["date"]),
        "section": section,
        "scope": disp,
        "summary": text,
        "issues": issues,
        "author": canon(r["author"], r["email"]),
        "people": {canon(r["author"], r["email"])} | {canon_name(n, e) for n, e in coauthors(msg)},
    })

# group
groups = {}
for c in included:
    key = (c["section"], c["scope"], c["summary"])
    groups.setdefault(key, []).append(c)

entries = []
for (section, scope, summary), cs in groups.items():
    cs.sort(key=lambda c: c["dt"], reverse=True)
    issues = []
    for c in cs:
        for n in c["issues"]:
            if n not in issues:
                issues.append(n)
    hashes = [c["hash"][:7] for c in cs]
    entries.append({
        "section": section,
        "scope": scope,
        "summary": summary,
        "issues": issues,
        "hashes": hashes,
        "newest": cs[0]["dt"],
    })

ORDER = ["breaking", "features", "fixes"]
TITLES = {"breaking": "## Breaking changes", "features": "## Features", "fixes": "## Fixes"}


def render(e):
    prefix = f"- **{e['scope']}:** "
    issues = "".join(f" (#{n})" for n in e["issues"])
    hashes = f" ({', '.join(e['hashes'])})"
    summary = e["summary"]
    line = prefix + summary + issues + hashes
    if len(line) > 100:
        avail = 100 - len(prefix) - len(issues) - len(hashes)
        cut = avail - 1
        if cut < 0:
            cut = 0
        truncated = summary[:cut].rstrip(" ") + "\u2026"
        line = prefix + truncated + issues + hashes
    return line


lines = ["# Release 4.2.0", ""]
for sec in ORDER:
    es = [e for e in entries if e["section"] == sec]
    if not es:
        continue
    es.sort(key=lambda e: (e["scope"], [-e["newest"].timestamp()]))
    es.sort(key=lambda e: (e["scope"], -e["newest"].timestamp()))
    lines.append(TITLES[sec])
    lines.append("")
    for e in es:
        lines.append(render(e))
    lines.append("")

# contributors
counts = {}
authored = set()
for c in included:
    authored.add(c["author"])
    for p in c["people"]:
        counts[p] = counts.get(p, 0) + 1
contrib = [(n, k) for n, k in counts.items() if not n.endswith("[bot]") and n in authored]
contrib.sort(key=lambda x: (-x[1], x[0]))
if contrib:
    lines.append("## Contributors")
    lines.append("")
    for n, k in contrib:
        lines.append(f"- {n} ({k})")

text = "\n".join(lines).rstrip("\n") + "\n"
open("RELEASE_NOTES.md", "w", encoding="utf-8").write(text)

# diagnostics
print("included commits:", len(included), "entries:", len(entries))
print("sections:", {s: sum(1 for e in entries if e['section'] == s) for s in ORDER})
for s in ORDER:
    for e in sorted([e for e in entries if e['section'] == s], key=lambda e: (e['scope'], -e['newest'].timestamp())):
        print(s, "|", render(e))
print("contributors:", contrib)
print("max line len:", max(len(l) for l in text.split("\n")))
"}

